function drawGeneratedAreaFallback(canvas,compiled){
 if(!canvas||!compiled)return false;
 canvas.width=717;canvas.height=842;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,717,842);
 c.fillStyle='#294e32';c.fillRect(0,0,717,842);
 const pf=compiled.playfield||{x:0,y:0,w:590,h:842};
 c.fillStyle='#6e9b4f';c.fillRect(pf.x,pf.y,pf.w,pf.h);
 // 草の細かな点。外部rendererが古い/未反映でもRuntimeSceneを視認できる最低保証。
 for(let y=pf.y+7;y<pf.y+pf.h;y+=13)for(let x=pf.x+7;x<pf.x+pf.w;x+=17){const n=((x*13+y*7)%29);if(n<7){c.fillStyle=n<3?'#4f7d41':'#96bd6d';c.fillRect(x,y,2,4)}}
 // Ver0.49: 4方向の仮実マップを見分けやすくする地形テーマ。最終美術ではなくSceneSpec確認用。
 const tpl=compiled.templateId||'';
 if(tpl==='branch_forest'){
  c.fillStyle='#315f38';c.fillRect(pf.x,pf.y,92,pf.h);c.fillRect(pf.x+pf.w-92,pf.y,92,pf.h);
  for(let yy=38;yy<805;yy+=72)for(const xx of [28,68,515,552]){c.fillStyle='#204b31';c.beginPath();c.arc(xx,yy,18,0,Math.PI*2);c.fill();c.fillStyle='#447b43';c.beginPath();c.arc(xx+5,yy-8,13,0,Math.PI*2);c.fill()}
 }else if(tpl==='riverside'){
  c.fillStyle='#2b79a8';c.fillRect(pf.x+pf.w-96,pf.y,96,pf.h);c.fillStyle='#5fb8d7';for(let yy=18;yy<820;yy+=34){c.fillRect(pf.x+pf.w-83,yy,54,3);c.fillRect(pf.x+pf.w-66,yy+9,35,2)}
  c.fillStyle='#9aa38c';for(const yy of [120,265,525,710])c.fillRect(pf.x+pf.w-118,yy,26,15);
 }else if(tpl==='terrace'){
  c.fillStyle='#77836d';c.fillRect(pf.x,pf.y+180,pf.w,28);c.fillRect(pf.x,pf.y+565,pf.w,32);c.fillStyle='#a5ad98';
  for(let xx=30;xx<560;xx+=42){c.fillRect(xx,pf.y+184,28,8);c.fillRect(xx+12,pf.y+572,28,8)}
 }
 const path=(sh,fill,stroke)=>{if(!sh)return;c.save();c.beginPath();if(sh.shape==='rect'){const[x,y,w,h]=sh.v;c.rect(x,y,w,h)}else if(sh.shape==='circle'){c.arc(sh.v[0],sh.v[1],sh.v[2],0,Math.PI*2)}else if(sh.shape==='poly'&&sh.v?.length){c.moveTo(sh.v[0][0],sh.v[0][1]);for(let i=1;i<sh.v.length;i++)c.lineTo(sh.v[i][0],sh.v[i][1]);c.closePath()}else{c.restore();return}c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=2;c.stroke()}c.restore()};
 for(const f of compiled.facilitySlots||[]){const b=f.bounds;if(!b)continue;c.save();c.globalAlpha=.78;c.fillStyle='#7fa45c';c.fillRect(b.x+4,b.y+4,Math.max(8,b.w-8),Math.max(8,b.h-8));c.restore()}
 for(const z of compiled.walkZones||[])path(z.pixelShape,'#c79d61','#a77a49');
 const sign=(x,y,t)=>{c.fillStyle='#5c4029';c.fillRect(x-3,y,6,27);c.fillStyle='#d8bd7c';c.fillRect(x-20,y-15,40,15);c.strokeStyle='#6f4c31';c.strokeRect(x-20,y-15,40,15);c.fillStyle='#3a362d';c.font='bold 9px sans-serif';c.textAlign='center';c.fillText(t,x,y-4)};
 for(const f of compiled.facilitySlots||[]){const b=f.bounds;if(!b)continue;c.fillStyle='#6b4a2d';c.fillRect(b.x+7,b.y+7,4,15);c.fillRect(b.x+b.w-11,b.y+7,4,15);if(f.slot<=3)sign(f.entrance.x,f.entrance.y-4,`区画${f.slot}`)}
 for(const z of compiled.serviceZones||[]){const b=z.bounds;if(!b)continue;c.fillStyle='#a47748';c.fillRect(b.x+12,b.y+12,22,17);c.fillStyle='#68472d';c.strokeRect(b.x+12,b.y+12,22,17)}
 for(const p of compiled.ports||[]){const sh=p.pixelShape;if(!sh||sh.shape!=='rect')continue;const[x,y,w,h]=sh.v,cx=x+w/2,cy=y+h/2;if(p.connected)sign(cx,Math.max(24,Math.min(810,cy)),window.FRENDA_FRONTIER?.areaDef?.(p.targetAreaId)?.name||'接続');else if(p.future)sign(cx,Math.max(24,Math.min(810,cy)),'未開拓')}
 // 右側コマンド欄。生成エリアでも中心と同じ操作位置を維持する。
 c.fillStyle='#062d54';c.fillRect(590,350,118,420);c.strokeStyle='#e6f3ff';c.lineWidth=3;c.strokeRect(590,350,118,420);c.fillStyle='#fff';c.font='bold 17px sans-serif';c.textAlign='left';c.fillText('▶ コマンド',602,374);const cmds=['💬 話す','🏠 家へ','🌱 相棒','🗺️ 冒険','🏪 お店','🔨 建設','👣 いどう','📖 図鑑'];c.font='bold 15px sans-serif';cmds.forEach((t,i)=>{const y=382+i*47;c.fillStyle=i===2?'#0d7a49':'#07549a';c.fillRect(599,y,100,38);c.strokeStyle='#78c6ff';c.strokeRect(599,y,100,38);c.fillStyle='#fff';c.fillText(t,606,y+25)});
 c.fillStyle='rgba(8,45,35,.88)';c.fillRect(18,782,330,40);c.fillStyle='#fff';c.font='bold 14px sans-serif';c.textAlign='left';c.fillText(`RuntimeScene：${compiled.areaName}`,31,807);
 return true;
}
async function drawTownVisual(s){
 const canvas=$("townVisualCanvas");if(!canvas)return;
 try{
  const [base,facility,detail,maxTown,playerSprite,partnerSprite,constructionAtlas,npcAtlas]=await Promise.all([
   loadVisual("frontier-asset-town-base-v031.png"),
   loadVisualOptional("frontier-asset-town-facilities-v031.png"),
   loadVisualOptional("frontier-asset-town-detail-v033.png"),
   loadVisualOptional("frontier-asset-town-max-v031.png"),
   loadVisualOptional("frontier-sprite-player-v031.png"),
   loadVisualOptional("frontier-sprite-partner-v031.png"),
   loadVisualOptional("frontier-asset-construction-v033.png"),
   loadVisualOptional("frontier-sprite-npcs-v033.png")
  ]);
  const c=canvas.getContext("2d");c.imageSmoothingEnabled=false;c.clearRect(0,0,canvas.width,canvas.height);
  const preset=F.townLayerTestPreset(s),rt=ensureTownRuntime(s),areaId=rt.areaId||F.townMovement(s).areaId;
  const drawNormal=()=>{
   if(F.areaDef?.(areaId)?.world?.runtimeGenerator==="scene-spec-v2"){const compiled=F.compileAreaScene?.(areaId,s);/* Ver0.44: generated area base is rendered inside UI itself. This removes cross-file renderer timing/cache dependency on iOS/GitHub Pages. */drawGeneratedAreaFallback(canvas,compiled);const cc=canvas.getContext("2d");if(npcAtlas&&compiled?.npcActivity){const parts=compiled.npcActivity.slice(0,4).map((n,i)=>({sprite:i%5,dx:n.anchor.x-20,dy:n.anchor.y-42,dw:40,dh:50}));drawNpcLayer(cc,npcAtlas,{parts})}drawTownActor(cc,playerSprite,rt.player,"player");drawTownActor(cc,partnerSprite,rt.partner,"partner");return;}
   c.drawImage(base,0,0,717,842);
   const states=F.townLayerStates(s).filter(x=>x.effective);
   const bands=F.TOWN_RENDER_BANDS||["ground","structure","low","character","front"];
   const drawBand=band=>{
    const off=document.createElement("canvas");off.width=717;off.height=842;
    const oc=off.getContext("2d");oc.imageSmoothingEnabled=false;
    const list=states.filter(x=>x.def.kind==="atlas"&&(x.def.band||"low")===band).sort((a,b)=>(a.def.z||0)-(b.def.z||0));
    for(const x of list){
     const defs=x.def.parts||[x.def.atlas];
     const src=x.def.asset==="detail"?detail:facility;
     if(!src)continue;
     for(const m of defs){if(!m)continue;oc.drawImage(src,m.sx,m.sy,m.sw,m.sh,m.dx*TOWN_MAP_X,m.dy*TOWN_MAP_Y,m.dw*TOWN_MAP_X,m.dh*TOWN_MAP_Y)}
    }
    c.drawImage(off,0,0);
    const npcs=states.filter(x=>x.def.kind==="npc"&&(x.def.band||"character")===band).sort((a,b)=>(a.def.z||0)-(b.def.z||0));
    for(const x of npcs)drawNpcLayer(c,npcAtlas,x.def)
   };
   for(const band of bands){if(band==="front"){drawTownActor(c,playerSprite,rt.player,'player');drawTownActor(c,partnerSprite,rt.partner,'partner')}drawBand(band);if(band==="structure")drawTownConstruction(c,s,constructionAtlas)}
   if(!bands.includes("front")){drawTownActor(c,playerSprite,rt.player,'player');drawTownActor(c,partnerSprite,rt.partner,'partner')}
  };
  if(areaId==="core"&&preset==="max"&&maxTown){
   c.drawImage(maxTown,0,0,717,842);
  }else{
   drawNormal();
  }
  if(F.townNavTestOverlay(s))drawTownNavOverlay(c,s);
  drawTownRoundTripGuides(c,s);
  if(townMoveRuntime.tap){c.save();c.strokeStyle='rgba(255,245,130,.95)';c.lineWidth=4;c.beginPath();c.arc(townMoveRuntime.tap.x,townMoveRuntime.tap.y,12,0,Math.PI*2);c.stroke();c.restore()}
  const d=$("townDialogOverlay");if(d)d.innerHTML=townDialogue(s);
 }catch(e){
  console.error(e);
  const c=canvas.getContext("2d");c.clearRect(0,0,canvas.width,canvas.height);c.fillStyle='#183b2b';c.fillRect(0,0,canvas.width,canvas.height);c.fillStyle='#fff';c.font='bold 24px sans-serif';c.textAlign='center';c.fillText('町画像の読み込みに失敗しました',canvas.width/2,canvas.height/2-10);c.font='16px sans-serif';c.fillText('必要な画像ファイルを同じフォルダへアップしてください',canvas.width/2,canvas.height/2+28);
  toast("町の画像を読み込めませんでした")
 }
}
function townSetMessage(text){townMoveRuntime.message=text||'';const d=$("townDialogOverlay");if(d)d.innerHTML=townDialogue(F.readSave())}
function townPersistPosition(){if(!townMoveRuntime.player||!townMoveRuntime.partner)return;F.setTownMovement(townMoveRuntime.player,townMoveRuntime.partner,townMoveRuntime.areaId||null)}
function setupTownMovement(){const canvas=$("townVisualCanvas");if(!canvas)return;canvas.onclick=e=>{if(e.target!==canvas)return;const s=F.readSave(),preset=F.townLayerTestPreset(s);if(preset==="max"){toast('最大発展表示では移動確認を停止しています');return}const rt=ensureTownRuntime(s),areaId=rt.areaId,r=canvas.getBoundingClientRect(),raw={x:(e.clientX-r.left)/r.width*canvas.width,y:(e.clientY-r.top)/r.height*canvas.height},m=F.townNavModel(s,"player",areaId),wr=m.worldRect;if(raw.x<wr.x||raw.y<wr.y||raw.x>=wr.x+wr.w||raw.y>=wr.y+wr.h)return;
 // Ver0.46: 画面端の出口へ続く道をタップした場合は、通常の「近い歩行セル」ではなく出口移動として扱う。
 const exitRoute=F.townExitTapAt?.(s,raw.x,raw.y,areaId);if(exitRoute){if(!exitRoute.open){toast('この道はまだ開通していません');return}if(!["prototype","ready"].includes(exitRoute.target?.world?.sceneStatus||"")){toast('この先のエリアはまだ準備中です');return}const target=F.townExitApproachPoint?.(s,exitRoute,"player",areaId);if(!target){toast('出口までの経路を作れませんでした');return}walkTownTo(target,{forcedExit:exitRoute});return}
 const target=F.townNearestWalkable(s,raw,"player",10,areaId);if(!target){toast('そこへは行けません');return}walkTownTo(target)};}
function startTownAreaTransition(rt,route){
 if(!rt||rt.transitioning||!route?.open||!route?.target||!route?.travel?.autoTransition||!["prototype","ready"].includes(route.target.world?.sceneStatus||""))return false;
 rt.transitioning=true;rt.moving=false;townPersistPosition();
 const fromAreaId=rt.areaId,targetAreaId=route.target.id,targetName=route.target?.name||"隣のエリア",overlay=$("townAreaTransition");
 if(overlay){overlay.textContent=`${route.travel.kindIcon||'🚶'} ${targetName}へ`;overlay.classList.add('on')}
 rt.token++;
 setTimeout(()=>{try{F.transitionTownArea(targetAreaId,fromAreaId);const s2=F.readSave(),mv=F.townMovement(s2);rt.areaId=mv.areaId;rt.player={...mv.player};rt.partner={...mv.partner};rt.trail=[];rt.tap=null;rt.message=`${targetName}へ着いた。`;rt.transitioning=false;if(overlay)overlay.classList.remove('on');renderAll()}catch(e){rt.transitioning=false;if(overlay)overlay.classList.remove('on');toast(e.message)}},Math.max(180,Number(route.travel.transitionMs)||260));
 return true;
}
function tryTownAreaAutoTransition(rt){if(!rt||rt.transitioning||!rt.player||!rt.areaId)return false;const latest=F.readSave(),route=F.townExitAt?.(latest,rt.player.x,rt.player.y,rt.areaId);return startTownAreaTransition(rt,route)}
function walkTownTo(target,opts={}){const s=F.readSave(),rt=ensureTownRuntime(s),areaId=rt.areaId,path=F.townFindPath(s,rt.player,target,"player",areaId),forcedExit=opts?.forcedExit||null;if(path.length<2){if(forcedExit&&startTownAreaTransition(rt,forcedExit))return;if(tryTownAreaAutoTransition(rt))return;toast('そこへは行けません');return}rt.token++;const token=rt.token;rt.moving=true;rt.transitioning=false;rt.tap={...target};rt.trail=[{...rt.player}];townSetMessage(forcedExit?`${forcedExit.target?.name||'隣のエリア'}へ向かいます。`:'そこまで歩いてみよう。');let i=1;const step=()=>{if(token!==rt.token||currentView!=='home'||homeMode!=='town'){rt.moving=false;return}if(i>=path.length){rt.moving=false;townPersistPosition();if(forcedExit&&startTownAreaTransition(rt,forcedExit))return;if(tryTownAreaAutoTransition(rt))return;const latest=F.readSave(),near=F.townNearestInteraction(latest,rt.player.x,rt.player.y,62);townSetMessage(near?`${near.label}の近くまで来た。ここから話したり調べたりできます。`:'町の中を自由に歩けます。行きたい場所をタップしてください。');setTimeout(()=>{rt.tap=null;drawTownVisual(F.readSave())},350);return}const next=path[i++];rt.trail.push({...rt.player});if(rt.trail.length>8)rt.trail.shift();rt.player={...next};if(rt.trail.length>=3){const follow=rt.trail[Math.max(0,rt.trail.length-3)];if(F.townPointWalkable(s,follow.x,follow.y,"partner",areaId))rt.partner={...follow}}if(!forcedExit&&tryTownAreaAutoTransition(rt))return;drawTownVisual(F.readSave());setTimeout(step,48)};step()}
function addHotspot(label,left,top,width,height,fn){const host=$('visualHotspots');if(!host)return;const b=document.createElement('button');b.className='visualHotspot';b.type='button';b.setAttribute('aria-label',label);b.title=label;Object.assign(b.style,{left:left+'%',top:top+'%',width:width+'%',height:height+'%'});b.onclick=fn;host.appendChild(b)}

function drawTownRoundTripGuides(c,s){
 const ts=F.townRoundTripTestState?.(s);if(!ts?.active)return;
 const areaId=F.townMovement(s).areaId,nav=F.areaNavDefinition?.(areaId)||F.areaDef?.(areaId)?.nav||{},targets=F.TOWN_ROUNDTRIP_TEST_TARGETS||[];
 const roundRect=(ctx,x,y,w,h,r)=>{r=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath()};
 const badge=(x,y,text,highlight=false)=>{c.save();c.font='bold 14px sans-serif';const w=Math.min(170,Math.max(78,c.measureText(text).width+22)),h=30;x=Math.max(6,Math.min(717-w-6,x-w/2));y=Math.max(6,Math.min(842-h-6,y-h/2));roundRect(c,x,y,w,h,10);c.fillStyle=highlight?'rgba(128,78,4,.92)':'rgba(8,43,77,.90)';c.fill();c.lineWidth=highlight?3:2;c.strokeStyle=highlight?'#ffe28a':'#e9f4ff';c.stroke();c.fillStyle='#fff';c.textAlign='center';c.textBaseline='middle';c.fillText(text,x+w/2,y+h/2+1);c.restore()};
 if(areaId==='core'){
  for(const t of targets){const ex=(nav.exits||[]).find(e=>e.to===t.areaId);if(!ex)continue;const done=!!ts.roundTrips?.[t.areaId],isNext=ts.next?.areaId===t.areaId;let x=ex.x+ex.w/2,y=ex.y+ex.h/2,label=t.label;if(ex.y<80){label='↑ '+label;y=36}else if(ex.y+ex.h>760){label='↓ '+label;y=700}else if(ex.x<60){label='← '+label;x=88}else if(ex.x+ex.w>540){label='→ '+label;x=500}if(done)label='✓ '+label;badge(x,y,label,isNext)}
 }else{
  const ex=(nav.exits||[]).find(e=>e.to==='core');if(ex){let x=ex.x+ex.w/2,y=ex.y+ex.h/2,label='中心開拓地へ';if(ex.y<80){label='↑ '+label;y=36}else if(ex.y+ex.h>760){label='↓ '+label;y=700}else if(ex.x<60){label='← '+label;x=88}else if(ex.x+ex.w>540){label='→ '+label;x=500}badge(x,y,label,true)}
 }
}
function drawTownNavOverlay(c,s){const m=F.townNavModel(s);c.save();c.font='bold 12px sans-serif';c.textAlign='center';c.textBaseline='middle';for(let y=0;y<m.rows;y++)for(let x=0;x<m.cols;x++){const px=x*m.cell,py=y*m.cell;c.fillStyle=m.grid[y][x]?'rgba(32,180,92,.14)':'rgba(220,52,52,.16)';c.fillRect(px,py,m.cell,m.cell)}c.strokeStyle='rgba(255,255,255,.16)';c.lineWidth=1;for(let x=0;x<=m.cols;x++){c.beginPath();c.moveTo(x*m.cell,0);c.lineTo(x*m.cell,m.scene.h);c.stroke()}for(let y=0;y<=m.rows;y++){c.beginPath();c.moveTo(0,y*m.cell);c.lineTo(m.scene.w,y*m.cell);c.stroke()}for(const ex of m.exits){c.fillStyle=ex.open?'rgba(0,210,255,.30)':'rgba(255,155,0,.38)';c.fillRect(ex.x,ex.y,ex.w,ex.h);c.fillStyle='#fff';c.fillText(ex.open?'↔':'🔒',ex.x+ex.w/2,ex.y+ex.h/2)}for(const it of m.interactions){c.strokeStyle='rgba(50,220,255,.95)';c.lineWidth=4;c.beginPath();c.arc(it.x,it.y,Math.max(14,Math.min(28,Number(it.r)||20)),0,Math.PI*2);c.stroke()}c.fillStyle='rgba(230,70,255,.9)';c.beginPath();c.arc(m.spawn.x,m.spawn.y,8,0,Math.PI*2);c.fill();const rt=ensureTownRuntime(s);c.fillStyle='rgba(255,235,70,.95)';c.beginPath();c.arc(rt.player.x,rt.player.y,7,0,Math.PI*2);c.fill();c.fillStyle='rgba(110,255,150,.95)';c.beginPath();c.arc(rt.partner.x,rt.partner.y,6,0,Math.PI*2);c.fill();c.restore()}
