function addToken(record,x,y,cls='partnerToken',label=''){if(!record||!image(record))return;const layer=$('tokenLayer'),canvas=$('sceneCanvas');if(!layer||!canvas)return;const cw=canvas.width||180,ch=canvas.height||240;const d=document.createElement('div');d.className=`pokemonToken ${cls}`;d.style.left=(x/cw*100)+'%';d.style.top=(y/ch*100)+'%';d.innerHTML=`<img src="${esc(image(record))}" alt="">`;layer.appendChild(d);if(label){const l=document.createElement('div');l.className='tokenLabel';l.style.left=(x/cw*100)+'%';l.style.top=((y+Math.max(16,ch/15))/ch*100)+'%';l.textContent=label;layer.appendChild(l)}}
